for(const [i,[type,b]]of Object.entries(Object.entries(BUILDINGS))){
 const el=document.createElement('button');el.className='building-card';el.dataset.type=type;el.title=`${b.name}. ${b.desc}`;el.setAttribute('aria-pressed','false');
 el.innerHTML=`<span class="building-icon">${b.icon}</span><span class="build-copy"><strong>${b.name}</strong><span class="build-effect">${buildBenefit(type)}</span><span class="catalog-cost" data-cost="${type}">${costs(b)}</span></span><span class="build-hotkey">${Number(i)<9?Number(i)+1:''}</span>`;
 el.onclick=()=>choose(type);$('buildings').append(el);
}
for(const [id,m]of Object.entries(MIRACLES)){
 const el=document.createElement('button');el.className='miracle-card';el.id=`miracle-${id}`;
 el.innerHTML=`<span class="miracle-symbol">${m.icon}</span><span><strong>${m.name}</strong><span class="miracle-description">${m.desc}</span><small></small></span>`;
 el.onclick=()=>{const result=miracle(state,id);if(result.ok){renderer.addEffect(id);toast(`${m.name} · ${state.name}`);save();update();checkDialogs();}else toast(result.reason);};$('miracles').append(el);
}
function update(){
 renderFoodWarnings();
 const r=state.resources,stats=workforceStats(state),marketPorters=state.citizens.filter(c=>c.tradeJob||c.saleJob).length,quarterPorters=state.citizens.filter(c=>c.districtJob).length,res=Object.fromEntries(Object.entries(RESOURCE_NAMES).map(([k,n])=>[k,['',n.toUpperCase()]]));
 setHTML($('resources'),Object.entries(res).map(([k,[icon,name]])=>`<div class="resource" title="${name}: ${rounded(r[k])}${MATERIALS.includes(k)?` / ${storage(state)}`:''}. Доставлено работниками: ${rounded(state.delivered[k]||0)}"><span class="resource-icon">${resourceIcon(k)}</span><div><strong class="${MATERIALS.includes(k)&&r[k]>storage(state)?'overflow':''}">${Math.floor(r[k])}</strong><small>${name}${k==='food'?` · семена ${foodAmount(seedReserve(state))}`:''}</small></div></div>`).join(''));
 $('population').title=`Дети: ${state.citizens.filter(c=>c.age<16).length} · взрослые: ${state.citizens.filter(c=>c.age>=16&&c.age<55).length} · пожилые: ${state.citizens.filter(c=>c.age>=55).length}`;$('population').textContent=`${state.population} / ${state.capacity}`;$('happiness').textContent=`☀ ${Math.round(state.happiness)}%`;$('happiness').style.color=state.happiness<40?'#aa654a':'';
 const efficiency=workers(state);const funeralLabels={gathering:'Жители собираются в храме',procession:'Толпа с факелами уходит в пустыню',jackals:'Шакалы уносят погребальный свёрток',returning:'Жители возвращаются домой'};$('mourning-notice').hidden=!state.funeral;if(state.funeral)$('mourning-notice').textContent=`${funeralLabels[state.funeral.stage]} · погибло ${state.funeral.deceased.length}. ${state.funeral.scope==='family'?'Семья провожает умерших; город продолжает работать.':'Работа приостановлена.'}`;const ground=!state.buildings.some(b=>b.type==='granary'&&(!b.construction||b.construction.kind==='upgrade'));$('ground-storage-note').hidden=!ground;$('ground-storage-note').textContent='Без амбара · запасы на земле у разгрузки';$('workers').textContent=`${stats.employed+stats.builders+(stats.carriers??0)+marketPorters+quarterPorters} / ${state.population}`;$('labor-meter').style.width=`${efficiency*100}%`;
 $('labor-note').textContent=state.funeral&&state.funeral.scope!=='family'?'Траурная процессия. Назначения и все грузы сохранены; работа продолжится после возвращения.':stats.disconnected?`Нет пути к ${stats.disconnected} рабочим зданиям. Нужен мост или склад на этом берегу.`:`Строители: ${stats.builders} · носильщики: ${stats.carriers??0} · площадки: ${stats.sites} · рынок: ${marketPorters} · склады: ${quarterPorters}. Собирают: ${stats.working} · несут груз: ${stats.carrying}. Ресурсы поступают только после доставки.`;
 $('date').title='1 год города = 2 года возраста. Дети работают с 16 лет.';$('date').textContent=`Год ${state.year} · ${SEASONS[state.season]}`;$('season-icon').textContent=['❀','☀','❧','❄'][state.season];
 setHTML($('season-track'),SEASONS.map((v,i)=>`<i class="${i===state.season?'current':''}" title="${v}"></i>`).join(''));
 $('god-name').textContent=state.name;$('god-rating').textContent=`Слава ${state.divinity.rating} · вдохновлено ${state.divinity.inspirationSuccesses} · вера людей ${Math.round(beliefMultiplier(state)*60)}%`;setHTML($('god-description'),MOURNING_NAMES.includes(state.name)?'Город помнит тех, кого потерял.<br>Люди называют бога по судьбе своих близких.':Object.values(state.divinity.domains).some(v=>v>0)?'Твоё имя рождается из деяний.<br>Деяния остаются в памяти людей.':'Люди строят город.<br>Ты выбираешь, каким богом стать.');
 $('god-level').textContent=count(state,'ziggurat')?'III · БОГ ВЕЛИКОГО ГОРОДА':state.population>=24?'II · ПОКРОВИТЕЛЬ ГОРОДА':'I · ДУХ ПОСЕЛЕНИЯ';$('pantheon').textContent=`Заслуженные имена · ${state.divinity.names.length}`;
 const weather=weatherAt(state);$('weather').textContent=state.drought?`☀ Засуха · ${state.drought} сез.`:state.rain?`☂ Благодатный дождь · ${state.rain} сез.`:({sunny:'☀ Ясно',cloudy:'☁ Облачно',rain:'☂ Дождь',wind:'≋ Ветер'}[weather.type]);$('weather').classList.toggle('drought',!!state.drought);

 const signature=`${state.news.length}|${state.news[0]?.title}|${state.tick}`;
 if(signature!==newsSignature){newsSignature=signature;$('news').innerHTML=state.news.map(n=>`<article class="news-item ${['good','bad','miracle','year','build','info'].includes(n.kind)?n.kind:'info'}"><small>ГОД ${n.year} · ${SEASONS[n.season].toUpperCase()}</small><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></article>`).join('');}
 const g=goals(state);setHTML($('goals'),g.map(v=>`<div class="goal ${v.done?'done':''}"><span>${v.done?'✓':'○'}</span>${v.label}</div>`).join(''));$('goal-number').textContent=`${g.filter(v=>v.done).length} / 5`;
 for(const [id,m]of Object.entries(MIRACLES)){
  const el=$(`miracle-${id}`);const reason=state.funeral?'Город провожает умерших':state.lost?'Поселение покинуто':state.event?'Реши событие':state.cooldowns[id]?`Через ${state.cooldowns[id]} сез.`:r.faith<m.cost?`Нужно ${m.cost} веры`:id==='cat'&&catReason(state)?catReason(state):id==='abundance'&&r.food>=storage(state)?'Амбары полны':'';
  el.disabled=!!reason;el.title=`${m.desc} Домен: ${DOMAIN_NAMES[m.domain]}. ${reason}`;el.querySelector('small').textContent=reason||`${m.cost} веры · ${DOMAIN_NAMES[m.domain]}`;
 }
 $('season-countdown').textContent=paused?'Время на паузе':`До сезона: ${Math.max(0,Math.ceil(45-state.seasonElapsed))} с`;
 $('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Продолжить время':'Приостановить время');$('pause').classList.toggle('active',paused);$('next-season').disabled=state.lost&&!state.funeral||!!state.event;
 const clock=lightingAt(state.simTime),minutes=Math.floor(clock.hour*60);
 $('day-cycle').textContent=`${clock.night>.5?'☾':'☀'} ${clock.label} · ${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')} · ${isWorkday(state.simTime)?'до ужина':'до утра'}`;
 $('day-cycle').setAttribute('aria-label',`Дождаться ${isWorkday(state.simTime)?'ужина':'утра'}. Время и хозяйство действительно продвинутся.`);$('day-cycle').disabled=state.lost&&!state.funeral||!!state.event;
 $('street-life').textContent=state.funeral?'Все жители провожают умерших · работы и доставки приостановлены':`Строят ${stats.builders} · доставляют на стройки ${stats.carriers??0} · с рынка ${marketPorters} · между складами ${quarterPorters} · на работе ${stats.working} · с грузом ${stats.carrying} · дома ${stats.atHome}`;
 $('delivery-log').textContent=state.lastDelivery?`${citizenName(state.lastDelivery.citizen)} ${state.lastDelivery.source==='market'?'доставил покупку':'доставил'}: ${resourceText(state.lastDelivery.cargo)}`:'Ресурсы поступают, когда груз доходит до склада';
 $('city').parentElement.classList.toggle('is-night',clock.night>.45);updateDetail();renderManagement();renderSupply();for(const el of document.querySelectorAll('[data-cost]'))setHTML(el,costs(BUILDINGS[el.dataset.cost]));$('open-construction').textContent=`Стройки · ${orderedSites(state).length}`;$('open-trade').textContent=state.trade.caravan?`● Торговля · ${state.trade.silver}`:`Торговля · ${state.trade.silver}`;$('open-trade').classList.toggle('caravan-here',state.trade.caravan?.phase==='trading');$('open-trade').title=marketStatus(state);
}
function openDialog(kind,html){modalKind=kind;dialog.dataset.kind=kind;$('dialog-content').innerHTML=`<div class="dialog-inner">${html}</div>`;if(!dialog.open)dialog.showModal();last=performance.now();}
function closeDialog(){dialog.close();modalKind=null;delete dialog.dataset.kind;last=performance.now();}
function intro(){
 openDialog('help',`<span class="eyebrow">НОВЫЙ ВАВИЛОН · ЖИВОЙ ГОРОД</span><span class="dialog-emblem">✺</span><h2>У каждого города есть жизнь.</h2><p>Теперь жители действительно работают: выходят из дома, собирают материалы и несут их на склад. Дом лекаря принимает заболевших за еду и тростник. Лекарей нужно отдельно вдохновить и обучить в храме; каждый год с практикой они повышают мастерство, до 5 уровня. Призвание ускоряет свою работу на 20%; дети легче вдохновляются, но трудятся только с 16 лет. Ночью они возвращаются домой и с 20:00 ужинают из домашнего запаса. Голод, здоровье, настроение и вера индивидуальны: самочувствие меняет темп труда, вера жителей усиливает храмовые подношения и даёт ежедневные молитвы. Семьи растят детей: они начинают работать с 16 лет, стареют и оставляют следующее поколение. Один год города равен двум годам возраста. Семье нужны свободные кровати; для рождения в городе должен быть совокупный запас еды на два сезона. При смерти от старости близкие проводят небольшой обряд; остальные работают. При длительном голоде жители умирают: город прерывает работу и провожает умерших к границе долины.</p><p>Шерстяные ткани производили в Шумере в III тысячелетии до н. э. В игре прядение объединено с ткачеством: овчарня → шерсть → мастерская → ткань для торговли.</p><div class="instructions"><b>01.</b> Заложи двор или поле: строители принесут материалы и возведут здание.<br><b>02.</b> Ячмень: весной нужны работники для посева, летом — канал с водой, осенью — сбор до зимней порчи. В карточке здания закрепи до двух работников; в карточке жителя можно вернуть «Авто». Вне полевых работ закреплённые земледельцы остаются на своих местах. Рыбалка, сады и охота дают еду круглый год.<br><b>03.</b> Храм — первый универсальный склад. Амбары хранят все материалы.<br><b>04.</b> Улучшения до III уровня тоже требуют доставки и работы. Ночью строители отдыхают.<br><b>05.</b> Поставь мост на воду и осваивай другой берег.<br><b>06.</b> Развивай дороги; вдохновляй жителей. Добывай глину и тростник на отмеченных местах, дерево в лесах, камень в карьерах. Рыбалка и охота дают общую еду. Построй рынок: караваны придут к нему по дорогам и разгрузят товары. Купленные материалы жители отнесут на склад.</div><p>Цель — зиккурат, 30 жителей и десятый год. Сезон — 45 секунд; сутки — 60 секунд. У ячменя конечный годовой урожай; другие производственные числа указаны за рейс работника.</p><div class="dialog-actions"><button class="primary" id="start-game">${loaded||state.tick?'Вернуться в город':'Да будет город'}</button></div><p class="keyboard-note">1–9 — постройки · пробел — пауза · Escape — отмена<br>Shift + перетаскивание — карта · ◫ — вся долина</p>`);
 $('start-game').onclick=()=>{closeDialog();paused=false;save();update();checkDialogs();};
}
function checkDialogs(){
 if(dialog.open||state.funeral)return;
 if(state.lost||state.won&&!state.continued){
  openDialog('end',`<span class="eyebrow">${state.lost?'ИСТОРИЯ ОСТАЛАСЬ В ГЛИНЕ':'ТВОЯ ПЕРВАЯ ЛЕГЕНДА'}</span><span class="dialog-emblem">${state.lost?'☾':'▲'}</span><h2>${state.lost?'В долине погасли огни.':'Город коснулся неба.'}</h2><p>${state.lost?'Люди покинули город. У новой истории может быть другое начало.':`Долина знает тебя как «${esc(state.name)}». Через руки твоих жителей прошло ${state.deliveries} доставок.`}</p><div class="dialog-stats"><div><strong>${state.year}</strong><small>ГОД ИСТОРИИ</small></div><div><strong>${state.population}</strong><small>ЖИТЕЛЕЙ</small></div><div><strong>${state.miracleCount}</strong><small>ЧУДЕС</small></div></div><div class="dialog-actions">${state.lost?'':'<button class="primary" id="continue-game">Продолжить историю</button>'}<button class="secondary" id="end-new">Новая долина</button></div>`);
  if($('continue-game'))$('continue-game').onclick=()=>{state.continued=true;closeDialog();save();update();checkDialogs();};$('end-new').onclick=askReset;return;
 }
 if(state.event){
  const ev=state.event,reason=eventReason(state);
  openDialog('event',`<span class="eyebrow">ГОД ${state.year} · РЕШЕНИЕ ПОКРОВИТЕЛЯ</span><div class="event-resources">${Object.entries(state.resources).map(([k,v])=>`<span><b>${Math.floor(v)}</b> ${RESOURCE_NAMES[k]}</span>`).join('')}</div><span class="dialog-emblem">${ev.id==='caravan'?'⛵':ev.id==='refugees'?'⌂':'✺'}</span><h2>${esc(ev.title)}</h2><p>${esc(ev.text)}</p>${reason?`<p class="warning-note">${reason}</p>`:''}<div class="dialog-actions"><button class="primary" id="event-accept" ${reason?'disabled':''}>${ev.id==='caravan'?'Обменять еду':ev.id==='refugees'?'Принять людей':'Устроить праздник'}</button><button class="secondary" id="event-skip">Сохранить запасы</button></div><p class="keyboard-note">Время на паузе. Ресурсы сверху остаются видны.</p>`);
  for(const choice of ['accept','skip'])$(`event-${choice}`).onclick=()=>{const result=resolveEvent(state,choice);if(result.ok){closeDialog();save();update();checkDialogs();}else toast(result.reason);};
 }
}
function pantheon(){
 openDialog('pantheon',`<span class="eyebrow">ИМЕНА РОЖДАЮТСЯ ИЗ ДЕЯНИЙ</span><span class="dialog-emblem">✺</span><h2>${esc(state.name)}</h2><p>Чудеса и успешное вдохновение развивают божественные имена. Чудо даёт +2 славы; успешное вдохновение — +3 славы и ремесленное деяние, отказ — −1 славы (не ниже нуля). Близкие по силе домены могут дать смешанное имя. Потери дают скорбные и смертельные имена; большие потери от голода — жестокие.</p><div class="domain-list">${Object.entries(DIVINE_NAMES).map(([domain,names])=>`<section><h3>${DOMAIN_NAMES[domain]} <small>${state.divinity.domains[domain]} деяний</small></h3>${names.map(name=>`<span class="divine-name ${state.divinity.names.includes(name)?'earned':''}">${state.divinity.names.includes(name)?'✓':'○'} ${name}</span>`).join('')}</section>`).join('')}</div>${state.divinity.names.some(n=>!Object.values(DIVINE_NAMES).flat().includes(n))?`<p>Особые имена: ${state.divinity.names.filter(n=>!Object.values(DIVINE_NAMES).flat().includes(n)).map(esc).join(' · ')}</p>`:''}<div class="dialog-actions"><button class="primary" id="close-pantheon">Вернуться в город</button></div>`);$('close-pantheon').onclick=closeDialog;
}
function newGame(){state=createGame();desiredRoles.clear();clearRoadRoute();roadMode=false;renderer.setRoadMode(false);selection=null;inspected=null;paused=true;loaded=false;closeDialog();$('tile-detail').hidden=true;document.body.classList.remove('is-building');for(const el of document.querySelectorAll('.building-card')){el.classList.remove('selected');el.setAttribute('aria-pressed','false');}renderer.effects=[];renderer.ambient=0;renderer.lightMode='auto';renderer.home();save();update();intro();}
function askReset(){openDialog('reset','<span class="dialog-emblem">↻</span><h2>Начать новую историю?</h2><p>Текущий город и его сохранение будут заменены новой долиной. Это действие нельзя отменить.</p><div class="dialog-actions"><button class="primary" id="confirm-reset">Начать заново</button><button class="secondary" id="cancel-reset">Остаться в городе</button></div>');$('confirm-reset').onclick=newGame;$('cancel-reset').onclick=()=>{closeDialog();checkDialogs();};}
$('building-count').textContent=Object.keys(BUILDINGS).length;
$('open-supply').onclick=showSupply;
$('open-roads').onclick=()=>{clearRoadRoute();if(selection)choose(selection);roadMode=!roadMode;renderer.setRoadMode(roadMode);$('open-roads').setAttribute('aria-pressed',String(roadMode));$('map-hint').textContent=roadMode?'Дороги: выбери участок · стрелки и Enter — с клавиатуры · Escape — выйти':'Выбери здание или жителя';};
renderer.onRoadSelect=road=>{if(dialog.open)return;if(routeFrom&&roadMode){routeTo=road.id;inspected=null;renderRoadRoute();}else roadDetail(road);};
$('open-trade').onclick=showTrade;
$('open-construction').onclick=()=>showManagement('construction');$('open-residents').onclick=()=>showManagement('residents');
$('reset').onclick=askReset;$('help').onclick=intro;$('pantheon').onclick=pantheon;
$('pause').onclick=()=>{if(state.lost&&!state.funeral)return;paused=!paused;save();update();};
for(const el of document.querySelectorAll('[data-speed]'))el.onclick=()=>{speed=Number(el.dataset.speed);for(const b of document.querySelectorAll('[data-speed]'))b.classList.toggle('active',b===el);};
$('next-season').onclick=()=>{advanceSeason(state);save();update();checkDialogs();};
$('day-cycle').onclick=()=>{const clock=lightingAt(state.simTime),target=isWorkday(state.simTime)?20.25:6,seconds=((target-clock.hour+24)%24)*DAY_SECONDS/24+.05;advanceTime(state,seconds);renderer.lightMode='auto';save();update();checkDialogs();};
$('zoom-in').onclick=()=>renderer.zoom=Math.min(3,renderer.zoom+.2);$('zoom-out').onclick=()=>renderer.zoom=Math.max(.3,renderer.zoom-.2);$('home').onclick=()=>renderer.home();$('overview').onclick=()=>renderer.overview();
dialog.addEventListener('cancel',e=>{e.preventDefault();if(['help','reset','pantheon','construction','residents','confirmation','trade'].includes(modalKind)){closeDialog();checkDialogs();}});
document.addEventListener('keydown',e=>{if(dialog.open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.code==='Space'&&e.target.tagName!=='BUTTON'){e.preventDefault();paused=!paused;save();update();}if(e.key==='Escape'){if(roadMode){clearRoadRoute();$('tile-detail').hidden=true;roadMode=false;renderer.setRoadMode(false);$('open-roads').setAttribute('aria-pressed','false');}if(selection)choose(selection);else{inspected=null;$('tile-detail').hidden=true;}}if(/^[1-9]$/.test(e.key))choose(Object.keys(BUILDINGS)[Number(e.key)-1]);});
document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden&&loaded)save();});
function frame(now){
 const dt=Math.min(250,Math.max(0,now-last));last=now;
 if(!document.hidden&&!paused&&!dialog.open&&(!state.lost||state.funeral)){const oldTick=state.tick;advanceTime(state,dt/1000*speed);if(state.tick!==oldTick||state.event||state.lost||state.won&&!state.continued){save();update();checkDialogs();}if(now-lastSave>3000){save();lastSave=now;}}
 if(now-lastUI>350){update();lastUI=now;}
 renderer.draw(state,selection,now);requestAnimationFrame(frame);
}
update();requestAnimationFrame(frame);
if(!loaded)intro();else{toast(legacyRaw?'Город обновлён: добавлены одежда и мастер одежды. Жители начинают с добротной одеждой; прежние запасы, семьи и грузы сохранены.':'Город и грузы восстановлены. Нажми ▶, когда будешь готов.');checkDialogs();}
if(corrupt)setTimeout(()=>toast('Сохранение повреждено или несовместимо. Начата новая история.'),500);
if(!storageOK){$('save-status').textContent='○ Без сохранения';setTimeout(()=>toast('Хранилище браузера недоступно. Прогресс сохранится только до закрытия вкладки.'),1000);}
